import{_ as t,o as s,c as o,ag as n}from"./chunks/framework.DoUXNnsN.js";const u=JSON.parse('{"title":"部署到IIS","description":"","frontmatter":{"title":"部署到IIS","aliases":["IIS部署","IIS","dotnet publish","Hosting Bundle","ASP.NET Core Module","ANCM","应用程序池",500.19,502.5],"tags":["dotNET","部署","IIS"],"status":"ai-draft","sources":["https://learn.microsoft.com/en-us/aspnet/core/host-and-deploy/iis/?view=aspnetcore-10.0","https://learn.microsoft.com/en-us/aspnet/core/host-and-deploy/iis/hosting-bundle?view=aspnetcore-10.0","https://learn.microsoft.com/en-us/aspnet/core/host-and-deploy/aspnet-core-module?view=aspnetcore-10.0","https://learn.microsoft.com/en-us/aspnet/core/test/troubleshoot-azure-iis?view=aspnetcore-10.0","https://learn.microsoft.com/en-us/aspnet/core/host-and-deploy/azure-iis-errors-reference?view=aspnetcore-10.0","本机实测 dotnet publish 与命令行运行已发布程序（.NET 10.0.401）"],"updated":"2026-10-21T00:00:00.000Z","order":9},"headers":[],"relativePath":"30-.NET生态/部署到IIS.md","filePath":"30-.NET生态/部署到IIS.md"}'),a={name:"30-.NET生态/部署到IIS.md"};function i(d,e,l,p,c,r){return s(),o("div",null,[...e[0]||(e[0]=[n(`<blockquote><p>本篇是 <a href="/Encyclopedia/30-.NET生态/dotNET">dotNET</a> Web 主线的最后一篇：把写好的 ASP.NET Core 程序放到 Windows 服务器的 IIS 上让别人访问。读完你应该能：说清&quot;发布 → 装 Hosting Bundle → 建应用程序池和站点 → 配权限和密钥 → 验证&quot;的完整流程；知道 IIS 和 Kestrel 是什么关系；看到 500.19、502.5、500.30 这些错误页时知道往哪里查。</p><p>⚠ <strong>本篇验证范围</strong>：我的电脑上 IIS 服务在运行、ASP.NET Core Module 也已安装，但<strong>当前会话没有管理员权限</strong>，无法创建站点和应用程序池，所以&quot;在 IIS 里建站并访问&quot;的部分<strong>未在本机运行验证</strong>，步骤以微软官方文档为准。<strong>已在本机实际验证</strong>的部分是：<code>dotnet publish</code> 的产物、生成的 <code>web.config</code>、已发布程序以 <code>Production</code> 环境运行时的行为（含缺少密钥时的报错）。每一节都会标明是哪一种。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>IIS（Internet Information Services）是 Windows 自带的 Web 服务器；&quot;部署到 IIS&quot;就是把 ASP.NET Core 程序发布成一个文件夹，让 IIS 通过 <strong>ASP.NET Core Module（ANCM）</strong> 启动并代理请求给它。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/30-.NET生态/ASP.NET-Core">ASP.NET-Core</a>：知道它自带的 Web 服务器叫 Kestrel。</li><li><a href="/Encyclopedia/30-.NET生态/dotNET运行时与SDK">dotNET运行时与SDK</a>：SDK、运行时（Runtime）、框架依赖 vs 自包含的区别。</li><li><a href="/Encyclopedia/30-.NET生态/配置与日志">配置与日志</a>：<code>appsettings.json</code>、环境变量、<code>ASPNETCORE_ENVIRONMENT</code>。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/HTTP">HTTP</a>：状态码 403/404/500/502 的大致含义。</li><li><a href="/Encyclopedia/30-.NET生态/身份认证与JWT">身份认证与JWT</a> 与 <a href="/Encyclopedia/30-.NET生态/HttpClient">HttpClient</a> 里的 <code>MesApi</code> 小服务，可作为本篇的发布对象。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>开发时我们用 <code>dotnet run</code>，程序自己带一个 Kestrel 服务器监听端口。放到生产环境后，你需要的是：开机自动启动、崩溃自动拉起、多个站点共用 80/443 端口、HTTPS 证书管理、日志、权限隔离……这些 IIS 都有现成的。很多工厂的服务器本来就是 Windows Server，运维人员熟悉 IIS，所以 MES 的 Web 部分常部署在 IIS 上。</p><h2 id="核心概念-由浅入深" tabindex="-1">核心概念（由浅入深） <a class="header-anchor" href="#核心概念-由浅入深" aria-label="Permalink to &quot;核心概念（由浅入深）&quot;">​</a></h2><h3 id="_1-iis-和-kestrel-的关系" tabindex="-1">1. IIS 和 Kestrel 的关系 <a class="header-anchor" href="#_1-iis-和-kestrel-的关系" aria-label="Permalink to &quot;1. IIS 和 Kestrel 的关系&quot;">​</a></h3><p>ASP.NET Core 程序<strong>一定有</strong> Kestrel。部署到 IIS 有两种托管模型：</p><table tabindex="0"><thead><tr><th>托管模型</th><th>做法</th><th>特点</th></tr></thead><tbody><tr><td><strong>进程内（InProcess）</strong></td><td>你的程序被加载进 IIS 的工作进程（<code>w3wp.exe</code>）里运行，不使用 Kestrel 监听端口</td><td>默认值，性能更好</td></tr><tr><td>进程外（OutOfProcess）</td><td>IIS 作为反向代理，把请求转发给独立运行的 Kestrel 进程</td><td>程序和 IIS 分开进程，可与其他反向代理共用同一套配置</td></tr></tbody></table><p>官方文档中 <code>hostingModel</code> 的默认值是 <code>InProcess</code>（我们 <code>dotnet publish</code> 生成的 <code>web.config</code> 里也写着 <code>hostingModel=&quot;inprocess&quot;</code>）。连接 IIS 和你的程序的桥梁就是 <strong>ASP.NET Core Module（ANCM）</strong>，一个装在 IIS 里的原生模块；<code>web.config</code> 里的 <code>&lt;handlers&gt;</code> 告诉 IIS&quot;所有请求交给 <code>AspNetCoreModuleV2</code>&quot;。</p><h3 id="_2-发布产物-两种方式" tabindex="-1">2. 发布产物：两种方式 <a class="header-anchor" href="#_2-发布产物-两种方式" aria-label="Permalink to &quot;2. 发布产物：两种方式&quot;">​</a></h3><p><code>dotnet run</code> 是开发用的；部署要用 <strong><code>dotnet publish</code></strong> 生成&quot;可以直接拷走的文件夹&quot;。</p><table tabindex="0"><thead><tr><th>方式</th><th>命令</th><th>服务器要求</th><th>本机实测大小</th></tr></thead><tbody><tr><td>框架依赖（Framework-dependent）</td><td><code>dotnet publish -c Release -o publish</code></td><td>服务器必须装有对应版本的 .NET 运行时（Hosting Bundle 里包含）</td><td>21 个文件，2.8 MB</td></tr><tr><td>自包含（Self-contained）</td><td><code>dotnet publish -c Release -r win-x64 --self-contained true -o publish_sc</code></td><td>不需要装运行时，把运行时一起打包</td><td>351 个文件，109 MB</td></tr></tbody></table><p>（两项数字都来自本机对 <code>MesApi</code> 项目的实测。）多数企业环境用框架依赖：包小，运行时由运维统一打补丁；自包含适合&quot;服务器不能装东西&quot;的场景，但每次安全补丁都要重新发布整个程序。</p><h3 id="_3-hosting-bundle" tabindex="-1">3. Hosting Bundle <a class="header-anchor" href="#_3-hosting-bundle" aria-label="Permalink to &quot;3. Hosting Bundle&quot;">​</a></h3><p>服务器上要装 <strong>.NET Hosting Bundle</strong>：它包含 .NET 运行时 + ASP.NET Core 共享框架 + ANCM 模块。官方文档强调两点：</p><ul><li><strong>先装 IIS，再装 Hosting Bundle</strong>。如果顺序反了，要把 Hosting Bundle 再运行一遍（Repair）。</li><li>装完可能需要重启 IIS（以管理员身份）：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>net stop was /y</span></span>
<span class="line"><span>net start w3svc</span></span></code></pre></div><p>官方文档还指出：ASP.NET Core 不对共享框架的补丁版本做自动前滚，升级 Hosting Bundle 之后要这样重启 IIS 或重启系统。</p><h3 id="_4-应用程序池-application-pool" tabindex="-1">4. 应用程序池（Application Pool） <a class="header-anchor" href="#_4-应用程序池-application-pool" aria-label="Permalink to &quot;4. 应用程序池（Application Pool）&quot;">​</a></h3><p>应用程序池是 IIS 里&quot;一组网站共用的工作进程 + 它的运行身份&quot;。要点：</p><ul><li><strong>.NET CLR 版本设为&quot;无托管代码（No Managed Code）&quot;</strong>：ASP.NET Core 自己启动运行时，不依赖老的 .NET Framework CLR（官方：可选但推荐）。</li><li><strong>一个站点用一个独立的应用程序池</strong>：官方列出的错误码里（500.34、500.35）说明了把进程内和进程外、或多个进程内应用放在同一个池里会出错。</li><li>池的**标识（Identity）**默认是 <code>ApplicationPoolIdentity</code>，对应一个虚拟账号 <code>IIS AppPool\\池名</code>，<strong>文件夹权限要授给它</strong>。</li></ul><h2 id="逐步例子" tabindex="-1">逐步例子 <a class="header-anchor" href="#逐步例子" aria-label="Permalink to &quot;逐步例子&quot;">​</a></h2><h3 id="例-1-本机已验证-发布" tabindex="-1">例 1（本机已验证）：发布 <a class="header-anchor" href="#例-1-本机已验证-发布" aria-label="Permalink to &quot;例 1（本机已验证）：发布&quot;">​</a></h3><p>对 <a href="/Encyclopedia/30-.NET生态/HttpClient">HttpClient</a> 篇的 <code>MesApi</code> 项目：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotnet publish -c Release -o publish</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=== 1 publish 框架依赖 ===</span></span>
<span class="line"><span>appsettings.Development.json</span></span>
<span class="line"><span>appsettings.json</span></span>
<span class="line"><span>MesApi.deps.json</span></span>
<span class="line"><span>MesApi.dll</span></span>
<span class="line"><span>MesApi.exe</span></span>
<span class="line"><span>MesApi.pdb</span></span>
<span class="line"><span>MesApi.runtimeconfig.json</span></span>
<span class="line"><span>MesApi.staticwebassets.endpoints.json</span></span>
<span class="line"><span>Microsoft.AspNetCore.Authentication.JwtBearer.dll</span></span>
<span class="line"><span>Microsoft.AspNetCore.OpenApi.dll</span></span>
<span class="line"><span>Microsoft.Bcl.Cryptography.dll</span></span>
<span class="line"><span>Microsoft.IdentityModel.Abstractions.dll</span></span>
<span class="line"><span>Microsoft.IdentityModel.JsonWebTokens.dll</span></span>
<span class="line"><span>Microsoft.IdentityModel.Logging.dll</span></span>
<span class="line"><span>Microsoft.IdentityModel.Protocols.dll</span></span>
<span class="line"><span>Microsoft.IdentityModel.Protocols.OpenIdConnect.dll</span></span>
<span class="line"><span>Microsoft.IdentityModel.Tokens.dll</span></span>
<span class="line"><span>Microsoft.OpenApi.dll</span></span>
<span class="line"><span>Swashbuckle.AspNetCore.SwaggerUI.dll</span></span>
<span class="line"><span>System.IdentityModel.Tokens.Jwt.dll</span></span>
<span class="line"><span>web.config</span></span>
<span class="line"><span>共 21</span></span>
<span class="line"><span>2.8M</span></span>
<span class="line"><span>=== 2 web.config ===</span></span>
<span class="line"><span>\uFEFF&lt;?xml version=&quot;1.0&quot; encoding=&quot;utf-8&quot;?&gt;</span></span>
<span class="line"><span>&lt;configuration&gt;</span></span>
<span class="line"><span>  &lt;location path=&quot;.&quot; inheritInChildApplications=&quot;false&quot;&gt;</span></span>
<span class="line"><span>    &lt;system.webServer&gt;</span></span>
<span class="line"><span>      &lt;handlers&gt;</span></span>
<span class="line"><span>        &lt;add name=&quot;aspNetCore&quot; path=&quot;*&quot; verb=&quot;*&quot; modules=&quot;AspNetCoreModuleV2&quot; resourceType=&quot;Unspecified&quot; /&gt;</span></span>
<span class="line"><span>      &lt;/handlers&gt;</span></span>
<span class="line"><span>      &lt;aspNetCore processPath=&quot;dotnet&quot; arguments=&quot;.\\MesApi.dll&quot; stdoutLogEnabled=&quot;false&quot; stdoutLogFile=&quot;.\\logs\\stdout&quot; hostingModel=&quot;inprocess&quot; /&gt;</span></span>
<span class="line"><span>    &lt;/system.webServer&gt;</span></span>
<span class="line"><span>  &lt;/location&gt;</span></span>
<span class="line"><span>&lt;/configuration&gt;</span></span></code></pre></div><ul><li>产物是一个文件夹：你的程序集 <code>MesApi.dll</code>、依赖的第三方 DLL、<code>appsettings*.json</code>、以及 <code>web.config</code>。</li><li><strong><code>web.config</code></strong> 是 <code>dotnet publish</code> 自动生成的，作用是让 IIS 知道怎么启动：<code>processPath=&quot;dotnet&quot; arguments=&quot;.\\MesApi.dll&quot;</code>（框架依赖时用 <code>dotnet</code> 启动 DLL）。自包含发布时，我实测这一行变为 <code>processPath=&quot;.\\MesApi.exe&quot;</code>。</li><li><code>stdoutLogEnabled=&quot;false&quot;</code>：默认不记录标准输出日志。排查启动故障时可临时改成 <code>true</code>（见后面&quot;排查&quot;）。</li><li>注意 <code>appsettings.Development.json</code> 也被发布出来了——<strong>里面如果有开发用密钥，就一起带到了服务器</strong>。这个文件只在 <code>Development</code> 环境才被读取，生产环境不读，但仍应在发布前确认不含敏感信息，或不把它拷到服务器。</li></ul><h3 id="例-2-本机已验证-在命令行以生产环境试跑已发布程序" tabindex="-1">例 2（本机已验证）：在命令行以生产环境试跑已发布程序 <a class="header-anchor" href="#例-2-本机已验证-在命令行以生产环境试跑已发布程序" aria-label="Permalink to &quot;例 2（本机已验证）：在命令行以生产环境试跑已发布程序&quot;">​</a></h3><p>在把文件夹拷到 IIS 之前，<strong>先在命令行直接跑一遍</strong>。这是官方排错文档推荐的方法：能暴露绝大多数启动问题，而且错误信息比 IIS 的错误页清楚得多。</p><p>PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd publish</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ASPNETCORE_ENVIRONMENT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Production&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet MesApi.dll </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">urls http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">localhost:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5202</span></span></code></pre></div><p>结果：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=== 1 Production 且没配密钥（dotnet MesApi.dll --urls http://localhost:5202）===</span></span>
<span class="line"><span>Unhandled exception. System.InvalidOperationException: 缺少 Jwt:Key 配置</span></span>
<span class="line"><span>   at Program.&lt;Main&gt;$(String[] args) in ...\\api\\Program.cs:line 33</span></span>
<span class="line"><span>=== 2 Production + 环境变量 Jwt__Key ===</span></span>
<span class="line"><span>GET /api/ping -&gt; 200</span></span>
<span class="line"><span>GET /openapi/v1.json -&gt; 404</span></span>
<span class="line"><span>GET /swagger/index.html -&gt; 404</span></span></code></pre></div><p>三点发现：</p><ol><li><strong>没配密钥时程序启动就抛异常退出</strong>——这正是 <a href="/Encyclopedia/30-.NET生态/身份认证与JWT">身份认证与JWT</a> 里&quot;缺少配置立即失败&quot;的设计。如果这是在 IIS 里，用户看到的会是 <strong>HTTP 500.30（进程内启动失败）</strong> 一类的错误页（官方文档把&quot;应用启动失败&quot;归在 500.30），具体要去事件查看器或 stdout 日志里才能看到真正原因 ——&quot;缺少 Jwt:Key 配置&quot;。这一条在 IIS 里的表现我<strong>未实测</strong>，仅根据官方错误码说明推断。</li><li>设置环境变量 <code>Jwt__Key</code> 后，服务正常启动：<code>/api/ping</code> 返回 200。</li><li>生产环境下 <code>/openapi/v1.json</code> 和 <code>/swagger</code> 都是 <strong>404</strong>，因为 <code>MapOpenApi</code> 和 Swagger UI 只在 <code>Development</code> 环境启用（见 <a href="/Encyclopedia/30-.NET生态/Swagger与OpenAPI">Swagger与OpenAPI</a>）。</li></ol><p>这里 <code>--urls</code> 在 IIS 进程内模式下不起作用（IIS 的绑定决定了地址），仅用于命令行试跑。</p><h3 id="例-3-⚠-未在本机运行验证-在-iis-里建站" tabindex="-1">例 3（⚠ 未在本机运行验证）：在 IIS 里建站 <a class="header-anchor" href="#例-3-⚠-未在本机运行验证-在-iis-里建站" aria-label="Permalink to &quot;例 3（⚠ 未在本机运行验证）：在 IIS 里建站&quot;">​</a></h3><blockquote><p>以下步骤来自微软官方文档和通行的 <code>appcmd</code> 用法。我的会话没有管理员权限，<strong>没有实际执行过</strong>；命令的细节（尤其路径、端口）请在你们的测试服务器上先试。<strong>不要直接在生产服务器上第一次尝试。</strong></p></blockquote><p><strong>准备（服务器上，管理员）：</strong></p><ol><li>确认 IIS 已启用（&quot;启用或关闭 Windows 功能&quot;里的 Internet Information Services，或服务器管理器里的 Web 服务器角色）。</li><li>安装 <strong>.NET Hosting Bundle</strong>（版本不低于你的程序目标版本，下载入口见官方文档）。装完执行 <code>net stop was /y</code> 与 <code>net start w3svc</code>。</li><li>验证模块已安装：文件 <code>C:\\Program Files\\IIS\\Asp.Net Core Module\\V2\\aspnetcorev2.dll</code> 存在（<strong>我的电脑上存在，文件版本是 20.0.26177.10</strong>），右键属性→详细信息可看版本。</li><li>把本机 <code>publish</code> 文件夹整个拷到服务器，例如 <code>C:\\sites\\MesApi</code>。部署更新时，官方建议先放一个 <code>app_offline.htm</code> 让 ANCM 优雅关闭程序、释放被占用的 DLL，拷完再删掉它。</li></ol><p><strong>图形界面（IIS 管理器）：</strong></p><ol><li>展开服务器节点 → <strong>应用程序池</strong> → 添加：名称 <code>MesApi</code>，&quot;.NET CLR 版本&quot;选&quot;无托管代码&quot;。</li><li><strong>网站</strong> → 添加网站：站点名称 <code>MesApi</code>，应用程序池选刚建的 <code>MesApi</code>，物理路径 <code>C:\\sites\\MesApi</code>，绑定填一个<strong>明确的主机名或具体 IP+端口</strong>（官方警告：不要使用顶级通配绑定如 <code>http://*:80/</code>，可能带来安全风险）。</li><li>给应用程序池身份授予文件夹权限：<code>IIS AppPool\\MesApi</code> 需要对 <code>C:\\sites\\MesApi</code> 有&quot;读取和执行&quot;，对需要写入的目录（日志目录 <code>logs</code>、上传目录等）要有&quot;修改&quot;权限。命令行写法（官方文档以 <code>DefaultAppPool</code> 举例用 <code>ICACLS</code>，权限级别请按最小权限原则取舍）：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icacls &quot;C:\\sites\\MesApi&quot; /grant &quot;IIS AppPool\\MesApi:(OI)(CI)RX&quot;</span></span>
<span class="line"><span>mkdir &quot;C:\\sites\\MesApi\\logs&quot;</span></span>
<span class="line"><span>icacls &quot;C:\\sites\\MesApi\\logs&quot; /grant &quot;IIS AppPool\\MesApi:(OI)(CI)M&quot;</span></span></code></pre></div><p><strong>命令行（<code>appcmd</code>，管理员）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%windir%\\system32\\inetsrv\\appcmd.exe add apppool /name:MesApi /managedRuntimeVersion:</span></span>
<span class="line"><span>%windir%\\system32\\inetsrv\\appcmd.exe add site /name:MesApi /physicalPath:C:\\sites\\MesApi /bindings:http/127.0.0.1:8081:</span></span>
<span class="line"><span>%windir%\\system32\\inetsrv\\appcmd.exe set app &quot;MesApi/&quot; /applicationPool:MesApi</span></span></code></pre></div><p>（<code>/managedRuntimeVersion:</code> 后面留空表示&quot;无托管代码&quot;。上面绑定到本机 8081 端口，仅用于测试。）</p><p><strong>配置环境变量与密钥：</strong></p><ul><li>环境变量 <code>ASPNETCORE_ENVIRONMENT=Production</code>，以及 <code>Jwt__Key</code>。官方文档的两种方式： <ul><li><p>在 <code>web.config</code> 的 <code>aspNetCore</code> 元素下加 <code>&lt;environmentVariables&gt;</code>（官方示例）：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">aspNetCore</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> processPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dotnet&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> arguments</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.\\MesApi.dll&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> hostingModel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;inprocess&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">environmentVariables</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">environmentVariable</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ASPNETCORE_ENVIRONMENT&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Production&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">environmentVariables</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">aspNetCore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>官方说明：<code>web.config</code> 里设置的环境变量优先于系统环境变量。<strong>但这等于把密钥写进了站点文件夹</strong>，不适合放 <code>Jwt__Key</code>。</p></li><li><p>为单个应用程序池设置环境变量（IIS 10 及以上），用 <code>appcmd</code> 的对应命令，见官方 IIS 参考文档里的 <code>environmentVariables</code> 条目；密钥更适合放这里或放专用密钥库，并限制只有管理员可读。</p></li></ul></li></ul><p><strong>验证：</strong></p><p>浏览器或 <code>curl</code> 访问 <code>http://127.0.0.1:8081/api/ping</code>，应返回 <code>pong</code>。</p><blockquote class="callout-warn"><p>⚠ 以上&quot;例 3&quot;没有实际执行。上线前请至少在一台测试服务器上完整走一遍并把过程记在你们自己的运维手册里。</p></blockquote><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p><strong>可以在你电脑上做的（不需要 IIS）：</strong></p><ol><li>在 <code>MesApi</code> 项目目录运行 <code>dotnet publish -c Release -o publish</code>，打开 <code>publish</code> 文件夹，找到 <code>web.config</code>、<code>MesApi.dll</code>、<code>appsettings.json</code>，对照本篇内容读懂 <code>web.config</code> 每个属性。</li><li>在 <code>publish</code> 目录用 PowerShell 按&quot;例 2&quot;试跑，分别验证：没设密钥时启动失败；设了 <code>Jwt__Key</code> 后 <code>/api/ping</code> 返回 200；<code>/swagger</code> 返回 404。</li><li>试一次自包含发布，对比文件数量和大小：<code>dotnet publish -c Release -r win-x64 --self-contained true -o publish_sc</code>（本机实测 351 个文件、109 MB），再看生成的 <code>web.config</code> 里 <code>processPath</code> 变成了什么。</li><li>做完删掉 <code>publish</code> 和 <code>publish_sc</code> 目录，并确认没有遗留的 <code>dotnet</code> 进程占着 5202 端口（<code>netstat -ano | findstr :5202</code>）。</li></ol><p><strong>需要你在测试服务器上做的（⚠ 本篇未验证）：</strong> 照&quot;例 3&quot;完整建一次站，并故意制造问题观察错误页：把应用程序池的 .NET 运行时卸载/改版本（模拟 500.31/500.30）、撤销 <code>IIS AppPool\\MesApi</code> 对文件夹的权限（观察 500.19 或 403 类现象）、去掉 <code>Jwt__Key</code>（观察 500.30）。每次都在&quot;事件查看器 → Windows 日志 → 应用程序&quot;里找来源为 <code>IIS AspNetCore Module</code> 的事件。</p><p><strong>本机 IIS 状态检查（只读，已实测）：</strong></p><table tabindex="0"><thead><tr><th>检查项</th><th>结果</th></tr></thead><tbody><tr><td><code>W3SVC</code>（万维网发布服务）、<code>WAS</code>（进程激活服务）</td><td>都是 Running</td></tr><tr><td><code>C:\\Program Files\\IIS\\Asp.Net Core Module\\V2\\aspnetcorev2.dll</code></td><td>存在，文件版本 20.0.26177.10</td></tr><tr><td>已装的 ASP.NET Core 共享框架</td><td>6.0.36、8.0.31、9.0.20、10.0.10、10.0.12</td></tr><tr><td><code>Get-WindowsOptionalFeature</code>、<code>appcmd list site</code></td><td>都因&quot;需要提升权限/无法读取配置&quot;失败——<strong>没有管理员权限，无法列出站点</strong></td></tr></tbody></table><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><p><strong>排查三板斧（来自官方文档）：</strong></p><ol><li>在服务器上<strong>用命令行直接运行</strong>已发布的程序（<code>dotnet MesApi.dll</code>，环境变量与线上一致），看控制台报什么。</li><li>看 <strong>事件查看器 → Windows 日志 → 应用程序</strong>，筛选来源 <code>IIS AspNetCore Module</code>。</li><li>临时打开 stdout 日志：新建 <code>logs</code> 目录，<code>web.config</code> 里改 <code>stdoutLogEnabled=&quot;true&quot; stdoutLogFile=&quot;.\\logs\\stdout&quot;</code>，并给应用程序池身份写入权限；复现问题后看最新的 <code>stdout_*.log</code>；<strong>排查完立刻改回 <code>false</code></strong>（官方警告：该日志没有大小上限，长期开启可能拖垮应用或服务器）。</li></ol><p><strong>错误码速查（依据微软官方排错文档与错误参考文档）：</strong></p><table tabindex="0"><thead><tr><th>错误页</th><th>常见原因</th><th>处理</th></tr></thead><tbody><tr><td><strong>500.19</strong></td><td>配置数据无效。官方&quot;错误参考&quot;里把它归于：IIS 角色/功能没装全、ASP.NET Core Module 没安装、或权限不对；另一种情形是子应用的 <code>web.config</code> 里又写了 <code>&lt;handlers&gt;</code>，与父应用冲突</td><td>确认已安装 Hosting Bundle（<code>aspnetcorev2.dll</code> 存在）并重启过 IIS；确认 IIS 功能已启用；检查应用程序池身份对站点文件夹（含 <code>web.config</code>）可读；子应用不要重复写 <code>&lt;handlers&gt;</code></td></tr><tr><td><strong>502.5 Process Failure</strong></td><td>工作进程没能启动。官方列出的常见原因：缺少所需的共享框架/运行时版本；位数（x86/x64）不匹配；<code>0x800701b1</code> 与某个 Windows 服务缺失有关</td><td>命令行直接运行看真实错误；装对应版本的运行时（Hosting Bundle）；应用程序池&quot;启用 32 位应用程序&quot;要与发布位数一致</td></tr><tr><td><strong>500.30 In-Process Startup Failure</strong></td><td>进程内的 CLR 启动失败：目标共享框架版本未安装，或你的 <code>Program.cs</code> 在启动阶段抛了异常（比如本篇的&quot;缺少 Jwt:Key&quot;）</td><td>事件查看器 / stdout 日志里看具体异常；检查已安装的 .NET 版本</td></tr><tr><td><strong>500.31 找不到原生依赖</strong></td><td>目标版本的 <code>Microsoft.NETCore.App</code> 或 <code>Microsoft.AspNetCore.App</code> 没装</td><td>装对应运行时，或改目标版本，或自包含发布</td></tr><tr><td><strong>500.0 In-Process Handler Load Failure</strong></td><td>ANCM 组件加载失败</td><td>修复安装 Hosting Bundle；见官方文档</td></tr><tr><td><strong>500.32 加载 dll 失败</strong></td><td>发布的位数与工作进程位数不一致</td><td>重新按匹配位数发布</td></tr><tr><td><strong>403.14 Forbidden</strong></td><td>部署目录不对、文件没拷全或没有 <code>web.config</code>，IIS 想列目录但被禁止</td><td>确认物理路径和文件夹里确实有 <code>MesApi.dll</code> 与 <code>web.config</code></td></tr><tr><td><strong>403 / 访问被拒（读不到文件）</strong></td><td>应用程序池身份没有文件夹权限</td><td>授权 <code>IIS AppPool\\池名</code></td></tr><tr><td><code>ERR_CONNECTION_REFUSED</code></td><td>网站被停止、绑定的地址/端口不对（官方错误参考：此时应用日志里没有记录）</td><td>检查站点状态与绑定</td></tr><tr><td>改了 DLL 后站点还是旧行为 / 拷贝时文件被占用</td><td>进程还在运行</td><td>先放 <code>app_offline.htm</code> 再拷文件，拷完删除它</td></tr><tr><td>升级了 Hosting Bundle 后程序不识别新框架</td><td>框架补丁版本不自动前滚、IIS 未重启</td><td><code>net stop was /y</code> 后 <code>net start w3svc</code></td></tr><tr><td>新装 Hosting Bundle 后仍报 ANCM 相关错误</td><td>先装了 Hosting Bundle 再装 IIS</td><td>再运行一次 Hosting Bundle 安装程序进行 Repair</td></tr><tr><td>生产环境密钥放在 <code>web.config</code> 或 <code>appsettings</code> 里被人看到</td><td>站点文件夹对运维/多人可读</td><td>放应用程序池环境变量或密钥库；限制文件夹读取权限</td></tr><tr><td>站点要写文件（日志、上传）失败</td><td>应用程序池身份没有写权限</td><td>只给特定目录&quot;修改&quot;权限，其他目录保持只读</td></tr></tbody></table><h2 id="业务视角与技术视角" tabindex="-1">业务视角与技术视角 <a class="header-anchor" href="#业务视角与技术视角" aria-label="Permalink to &quot;业务视角与技术视角&quot;">​</a></h2><ul><li><strong>业务视角</strong>：MES 的 Web 端一旦上线，就是产线 24 小时在用的系统。&quot;发布&quot;不是把文件拷过去就完，而是一次需要变更审批、回滚预案和停机窗口的操作（见 <a href="/Encyclopedia/80-电子制造业务/QMS/变更管理ECN-ECR">变更管理ECN-ECR</a> 的思想：任何影响生产的变更都要可追溯）。部署手册、回滚步骤、联系人写清楚，比技术本身更重要。</li><li><strong>技术视角</strong>：区分好三个环境（开发、测试、生产）的配置：连接串、密钥、日志级别、是否开放接口文档，都通过<strong>环境变量</strong>或密钥库注入，而不是改代码重新发布。数据库连接（见 <a href="/Encyclopedia/30-.NET生态/SqlSugar">SqlSugar</a>）用 Windows 集成认证时，要注意此时连数据库的身份是<strong>应用程序池身份</strong>，而不是你开发时登录的账号——数据库侧要给它授权，这是&quot;本机能跑、上线连不上库&quot;的头号原因。Windows 服务和 IIS 是两种不同的托管方式，需要后台常驻任务时见 <a href="/Encyclopedia/30-.NET生态/后台服务与Windows服务">后台服务与Windows服务</a>。</li></ul><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>练习 1</strong>：<code>dotnet run</code> 和 <code>dotnet publish</code> 的区别？生产环境为什么不用 <code>dotnet run</code>？</p><p>答案：<code>dotnet run</code> 在开发时编译并运行，使用 Debug 配置和开发环境设置，依赖源码和 SDK；<code>dotnet publish</code> 生成 Release 配置的、可直接部署的文件夹（含 <code>web.config</code>），服务器上只需运行时，不需要 SDK 和源码。</p><p><strong>练习 2</strong>：为什么应用程序池的 .NET CLR 版本要设成&quot;无托管代码&quot;？</p><p>答案：ASP.NET Core 在自己的进程/运行时里运行，由 ANCM 启动，不依赖 IIS 加载老的 .NET Framework CLR。官方文档称这一设置是可选但推荐的。</p><p><strong>练习 3</strong>：网站打开显示 502.5，你的第一步排查是什么？</p><p>答案：在服务器上用命令行进入发布目录，直接运行 <code>dotnet 程序名.dll</code>（环境变量与线上一致），看控制台的真实错误；同时看事件查看器中来源为 <code>IIS AspNetCore Module</code> 的事件。502.5 表示工作进程没能起来，原因常是缺运行时、位数不匹配或程序启动即崩溃。</p><p><strong>练习 4</strong>：本篇例 2 里，没设置 <code>Jwt__Key</code> 就启动，程序抛 <code>缺少 Jwt:Key 配置</code> 并退出。放到 IIS 上你会看到什么？怎么找到真正原因？</p><p>答案：浏览器看到的是进程内启动失败的错误页（500.30 一类，<strong>未在 IIS 上实测</strong>）。真正原因要在事件查看器的 <code>IIS AspNetCore Module</code> 事件或临时打开的 stdout 日志里看到那条异常信息；或者在服务器命令行直接运行同样的程序复现。</p><p><strong>练习 5（动手）</strong>：运行 <code>dotnet publish -c Release -o publish</code>，然后在 <code>publish</code> 目录里找出 <code>web.config</code>，回答：<code>processPath</code> 和 <code>arguments</code> 分别是什么？</p><p>答案（本机实测）：<code>processPath=&quot;dotnet&quot;</code>，<code>arguments=&quot;.\\MesApi.dll&quot;</code>；<code>hostingModel=&quot;inprocess&quot;</code>；<code>stdoutLogEnabled=&quot;false&quot;</code>；<code>stdoutLogFile=&quot;.\\logs\\stdout&quot;</code>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>流程：<code>dotnet publish</code> → 服务器装 Hosting Bundle（先 IIS 后 Bundle，装完重启 IIS）→ 应用程序池（无托管代码）+ 站点 → 授权 <code>IIS AppPool\\池名</code> → 环境变量/密钥 → 验证。</li><li>进程内（默认）和进程外两种托管模型；<code>web.config</code> 由 <code>dotnet publish</code> 生成。</li><li>排错三板斧：命令行直接跑、事件查看器、临时 stdout 日志（用完关掉）。</li><li>密钥别写进站点文件夹，用环境变量或密钥库；文档/Swagger 默认只在开发环境开放。</li><li>本篇未验证的部分：实际在 IIS 里建站、授权、访问、各类错误页的真实出现条件。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/30-.NET生态/dotNET">dotNET</a>、<a href="/Encyclopedia/30-.NET生态/ASP.NET-Core">ASP.NET-Core</a>、<a href="/Encyclopedia/30-.NET生态/dotNET运行时与SDK">dotNET运行时与SDK</a>、<a href="/Encyclopedia/30-.NET生态/配置与日志">配置与日志</a>、<a href="/Encyclopedia/30-.NET生态/身份认证与JWT">身份认证与JWT</a>、<a href="/Encyclopedia/30-.NET生态/Swagger与OpenAPI">Swagger与OpenAPI</a>、<a href="/Encyclopedia/30-.NET生态/后台服务与Windows服务">后台服务与Windows服务</a>、<a href="/Encyclopedia/30-.NET生态/SqlSugar">SqlSugar</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>微软：<a href="https://learn.microsoft.com/en-us/aspnet/core/host-and-deploy/iis/?view=aspnetcore-10.0" target="_blank" rel="noreferrer">在 Windows 上用 IIS 托管 ASP.NET Core</a></li><li>微软：<a href="https://learn.microsoft.com/en-us/aspnet/core/host-and-deploy/iis/hosting-bundle?view=aspnetcore-10.0" target="_blank" rel="noreferrer">Hosting Bundle</a>、<a href="https://learn.microsoft.com/en-us/aspnet/core/host-and-deploy/aspnet-core-module?view=aspnetcore-10.0" target="_blank" rel="noreferrer">ASP.NET Core Module</a></li><li>微软：<a href="https://learn.microsoft.com/en-us/aspnet/core/test/troubleshoot-azure-iis?view=aspnetcore-10.0" target="_blank" rel="noreferrer">IIS 与 Azure 上的排错</a>、<a href="https://learn.microsoft.com/en-us/aspnet/core/host-and-deploy/azure-iis-errors-reference?view=aspnetcore-10.0" target="_blank" rel="noreferrer">常见错误参考</a></li></ul>`,84)])])}const g=t(a,[["render",i]]);export{u as __pageData,g as default};
